#include <stdio.h>
/*
 * ex05：主频高不等于更快 —— 用「单指令耗时 = CPI / 主频」比较两台机器
 *   A: CPI=1.5, 3.0GHz -> 1.5/3e9 s = 0.50 ns
 *   B: CPI=1.0, 2.5GHz -> 1.0/2.5e9 s = 0.40 ns
 * 结论：B 主频更低但 CPI 更优，反而更快（加速比 1.25）。
 * 这就是为什么只看 GHz 选 CPU 是外行：架构（CPI）与主频要一起看。
 */
int main(void) {
    double fA = 3.0e9, cpiA = 1.5;   /* 机器 A：高主频、高 CPI */
    double fB = 2.5e9, cpiB = 1.0;   /* 机器 B：低主频、低 CPI */

    double tA = cpiA / fA;           /* 单条指令平均耗时（秒） */
    double tB = cpiB / fB;
    double speedup = tA / tB;        /* A 的耗时是 B 的多少倍 */

    printf("机器A: 主频=%.1fGHz CPI=%.1f -> 单指令耗时=%.2f ns\n", fA / 1e9, cpiA, tA * 1e9);
    printf("机器B: 主频=%.1fGHz CPI=%.1f -> 单指令耗时=%.2f ns\n", fB / 1e9, cpiB, tB * 1e9);
    printf("结论: %s 更快\n", tB < tA ? "机器B(主频低但CPI更优)" : "机器A");
    printf("A 相对 B 的耗时倍数 = %.3f (即 B 快 %.1f%%)\n", speedup, (speedup - 1) * 100.0);
    return 0;
}
